COMMENT ON COLUMN grade.urogenital_subscale_score IS
    'Urogenital subscale score (sexual, bladder, vaginal dryness), range 0-12.';
COMMENT ON COLUMN grade.overall_severity IS
    'Overall symptom severity: none, mild, moderate, or severe.';
COMMENT ON COLUMN grade.hrt_eligibility IS
    'HRT eligibility: eligible, eligible-with-caution, contraindicated, or empty string.';
COMMENT ON COLUMN grade.graded_at IS
    'Timestamp when the grading was computed.';

COMMENT ON COLUMN grade.assessment_id IS
    'Foreign key to the assessment table.';
COMMENT ON COLUMN grade.id IS
    'Primary key UUID, auto-generated.';
COMMENT ON COLUMN grade.created_at IS
    'Timestamp when this row was created.';
COMMENT ON COLUMN grade.updated_at IS
    'Timestamp when this row was updated.';
COMMENT ON COLUMN grade.deleted_at IS
    'Timestamp when this row was deleted.';

-- ========================================================================
-- END 90_create_table_grade.sql
-- ========================================================================

-- ========================================================================
-- BEGIN 91_create_table_grading_fired_rule.sql
-- ========================================================================

CREATE TABLE grading_fired_rule (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,
    grade_id UUID NOT NULL
        REFERENCES grade(id) ON DELETE CASCADE,
    rule_id VARCHAR(20) NOT NULL,
    category VARCHAR(100) NOT NULL DEFAULT '',
    description TEXT NOT NULL DEFAULT '',
    severity_level VARCHAR(15) NOT NULL DEFAULT ''
        CHECK (severity_level IN ('none', 'mild', 'moderate', 'severe', ''))
);

CREATE TRIGGER trigger_grading_fired_rule_updated_at
    BEFORE UPDATE ON grading_fired_rule
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

COMMENT ON TABLE grading_fired_rule IS
    'Individual HRT eligibility and severity rules that evaluated to true during MRS grading.';
COMMENT ON COLUMN grading_fired_rule.rule_id IS
    'Identifier of the rule that fired (e.g. VM-001, BH-002, CV-003, CI-004).';
COMMENT ON COLUMN grading_fired_rule.category IS
    'Category of the rule (e.g. Vasomotor, Bone Health, Cardiovascular, Breast Health, Contraindication).';
COMMENT ON COLUMN grading_fired_rule.description IS
    'Human-readable description of the rule.';
COMMENT ON COLUMN grading_fired_rule.severity_level IS
    'Severity level contributed by this rule: none, mild, moderate, severe, or empty string.';

COMMENT ON COLUMN grading_fired_rule.grade_id IS
    'Foreign key to the grade table.';
COMMENT ON COLUMN grading_fired_rule.id IS
    'Primary key UUID, auto-generated.';
COMMENT ON COLUMN grading_fired_rule.created_at IS
    'Timestamp when this row was created.';
COMMENT ON COLUMN grading_fired_rule.updated_at IS
    'Timestamp when this row was updated.';
COMMENT ON COLUMN grading_fired_rule.deleted_at IS
    'Timestamp when this row was deleted.';

-- ========================================================================
-- END 91_create_table_grading_fired_rule.sql
-- ========================================================================

